-- ---------------------------------------------------------------------------------------------------------------
-- Integrity rules the schema language cannot say (hand-written).

-- Money is positive integer cents (D-04); a line's plan may be zero.
ALTER TABLE "BudgetLine"   ADD CONSTRAINT "BudgetLine_planned_nonneg" CHECK ("plannedCents" >= 0);
ALTER TABLE "SpendRequest" ADD CONSTRAINT "SpendRequest_amount_pos"   CHECK ("amountCents" > 0);
ALTER TABLE "Commitment"   ADD CONSTRAINT "Commitment_amount_pos"     CHECK ("amountCents" > 0);
ALTER TABLE "Commitment"   ADD CONSTRAINT "Commitment_remaining_le_amount" CHECK ("remainingCents" <= "amountCents");
ALTER TABLE "Invoice"      ADD CONSTRAINT "Invoice_amount_pos"        CHECK ("amountCents" > 0);
ALTER TABLE "InvoiceMatch" ADD CONSTRAINT "InvoiceMatch_amount_pos"   CHECK ("amountCents" > 0);
ALTER TABLE "Reallocation" ADD CONSTRAINT "Reallocation_amount_pos"   CHECK ("amountCents" > 0);
ALTER TABLE "Reallocation" ADD CONSTRAINT "Reallocation_two_lines"    CHECK ("fromLineId" <> "toLineId");
ALTER TABLE "Period"       ADD CONSTRAINT "Period_index_month"        CHECK ("index" BETWEEN 1 AND 12);

-- E-INV-02 / D-05: a commitment exists only for an approved request of the same org, for no more than it asked.
-- In the database so that no code path, present or future, can issue a PO without an approval.
CREATE FUNCTION earmark_commitment_guard() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE
  req_state "RequestState";
  req_amount BIGINT;
BEGIN
  SELECT state, "amountCents" INTO req_state, req_amount FROM "SpendRequest" WHERE id = NEW."requestId" AND "orgId" = NEW."orgId";
  IF NOT FOUND OR req_state <> 'approved' THEN
    RAISE EXCEPTION 'E-INV-02: a commitment needs an approved request' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW."amountCents" > req_amount THEN
    RAISE EXCEPTION 'E-INV-02: a commitment cannot exceed its request' USING ERRCODE = 'check_violation';
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER earmark_commitment_guard BEFORE INSERT OR UPDATE OF "requestId", "amountCents", "orgId" ON "Commitment"
  FOR EACH ROW EXECUTE FUNCTION earmark_commitment_guard();
